<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import { useFloating, type PopupPlacement } from './internal/floating';
import { parseTime, formatTime, type TimeFormat, type TimeParts } from './internal/time';
import './styles/theme.css'; import './styles/field.css'; import './styles/floating.css'; import './styles/time-picker.css';
const props = withDefaults(defineProps<{ modelValue?: string | null; defaultValue?: string | null; format?: TimeFormat; hourStep?: number; minuteStep?: number; secondStep?: number; disabledHours?: () => number[]; disabledMinutes?: (hour: number) => number[]; disabledSeconds?: (hour: number, minute: number) => number[]; minTime?: string; maxTime?: string; placeholder?: string; size?: 'sm' | 'md' | 'lg'; label?: string; hint?: string; error?: string; disabled?: boolean; allowClear?: boolean; showNow?: boolean; open?: boolean; placement?: PopupPlacement }>(), { defaultValue: null, format: 'HH:mm', hourStep: 1, minuteStep: 1, secondStep: 1, placeholder: '选择时间', size: 'md', allowClear: true, showNow: true, placement: 'bottom-start' });
const emit = defineEmits<{ 'update:modelValue': [value: string | null]; change: [value: string | null, parts: TimeParts | null]; 'update:open': [value: boolean] }>();
const inner = ref(props.defaultValue); const innerOpen = ref(false); const current = computed(() => props.modelValue === undefined ? inner.value : props.modelValue); const opened = computed(() => (props.open ?? innerOpen.value) && !props.disabled); const draft = ref<TimeParts>(parseTime(current.value) ?? { hour: 0, minute: 0, second: 0 });
function setOpen(value: boolean) { if (props.disabled) return; if (props.open === undefined) innerOpen.value = value; emit('update:open', value); }
const { anchor, panel, position, resolvedPlacement } = useFloating(() => opened.value, () => props.placement, () => setOpen(false));
watch(opened, value => { if (value) draft.value = parseTime(current.value) ?? { hour: 0, minute: 0, second: 0 }; });
const seconds = (parts: TimeParts) => parts.hour * 3600 + parts.minute * 60 + parts.second;
function outOfBounds(parts: TimeParts) { const min = parseTime(props.minTime), max = parseTime(props.maxTime); return !!((min && seconds(parts) < seconds(min)) || (max && seconds(parts) > seconds(max))); }
function isDisabled(key: keyof TimeParts, value: number) { if (key === 'hour') { const min = parseTime(props.minTime), max = parseTime(props.maxTime); return !!props.disabledHours?.().includes(value) || !!((min && value < min.hour) || (max && value > max.hour)); } if (key === 'minute') return !!props.disabledMinutes?.(draft.value.hour).includes(value) || (outOfBounds({ ...draft.value, minute: value, second: 0 }) && outOfBounds({ ...draft.value, minute: value, second: 59 })); return !!props.disabledSeconds?.(draft.value.hour, draft.value.minute).includes(value) || outOfBounds({ ...draft.value, second: value }); }
const columns = computed(() => [{ key: 'hour' as const, label: '时', count: 24, step: props.hourStep }, { key: 'minute' as const, label: '分', count: 60, step: props.minuteStep }, ...(props.format === 'HH:mm:ss' ? [{ key: 'second' as const, label: '秒', count: 60, step: props.secondStep }] : [])].map(column => ({ ...column, values: Array.from({ length: Math.ceil(column.count / Math.max(1, column.step)) }, (_, index) => index * Math.max(1, column.step)) })));
function update(value: string | null) { if (props.modelValue === undefined) inner.value = value; emit('update:modelValue', value); emit('change', value, parseTime(value)); }
function commit(parts: TimeParts, close = false) { if (outOfBounds(parts) || props.disabledHours?.().includes(parts.hour) || props.disabledMinutes?.(parts.hour).includes(parts.minute) || props.disabledSeconds?.(parts.hour, parts.minute).includes(parts.second)) return; draft.value = parts; update(formatTime(parts, props.format)); if (close) { setOpen(false); anchor.value?.focus(); } }
function now() { const date = new Date(); commit({ hour: date.getHours(), minute: date.getMinutes(), second: props.format === 'HH:mm:ss' ? date.getSeconds() : 0 }, true); }
function key(event: KeyboardEvent, column: typeof columns.value[number]) { const values = column.values.filter(value => !isDisabled(column.key, value)); const at = values.indexOf(draft.value[column.key]); let next: number | undefined; if (event.key === 'ArrowDown') next = values[Math.min(at + 1, values.length - 1)]; if (event.key === 'ArrowUp') next = values[Math.max(0, at - 1)]; if (event.key === 'Home') next = values[0]; if (event.key === 'End') next = values.at(-1); if (event.key === 'Enter') { event.preventDefault(); commit(draft.value, true); } if (next !== undefined) { event.preventDefault(); commit({ ...draft.value, [column.key]: next }); } }
</script>
<template><div class="at-field"><label v-if="label" class="at-field__label">{{ label }}</label><div ref="anchor" :class="['at-selector', `at-selector--${size}`, 'at-time-picker', { 'at-selector--open': opened, 'at-selector--disabled': disabled, 'at-selector--error': error }]" role="combobox" :tabindex="disabled ? -1 : 0" aria-haspopup="dialog" :aria-label="label ?? placeholder" :aria-expanded="opened" @click="setOpen(!opened)" @keydown.enter.prevent="opened ? commit(draft, true) : setOpen(true)" @keydown.space.prevent="setOpen(!opened)" @keydown.down.prevent="setOpen(true)"><span :class="['at-selector__value', { 'at-selector__placeholder': !current }]">{{ current ?? placeholder }}</span><button v-if="allowClear && current && !disabled" type="button" class="at-selector__clear" aria-label="清空时间" @click.stop="update(null)">×</button><span aria-hidden="true">◷</span></div><span v-if="error" class="at-field__error" role="alert">{{ error }}</span><span v-else-if="hint" class="at-field__hint">{{ hint }}</span><Teleport to="body"><div v-if="opened" ref="panel" class="at-popup at-time-picker__popup" :style="position" :data-placement="resolvedPlacement" role="dialog" :aria-label="label ?? placeholder"><div class="at-time-picker__columns"><ul v-for="column in columns" :key="column.key" class="at-time-picker__column" role="listbox" :aria-label="column.label" tabindex="0" @keydown="key($event, column)"><li v-for="value in column.values" :key="value" role="option" :aria-selected="draft[column.key] === value" :aria-disabled="isDisabled(column.key, value)" :class="['at-time-picker__cell', { 'at-time-picker__cell--selected': draft[column.key] === value, 'at-time-picker__cell--disabled': isDisabled(column.key, value) }]" @click="!isDisabled(column.key, value) && commit({ ...draft, [column.key]: value })">{{ String(value).padStart(2, '0') }}</li></ul></div><div class="at-popup__footer at-time-picker__footer"><button v-if="showNow" type="button" class="at-time-picker__link" @click="now">此刻</button><span v-else /><button type="button" class="at-time-picker__ok" @click="commit(draft, true)">确定</button></div></div></Teleport></div></template>
